renderResult(result, { expanded }, theme, renderContext) {
  const text = stripTerminalSequences(result.content[0]?.type === "text" ? result.content[0].text : "").replace(/[\u0000-\u0008\u000b-\u001f\ufff9-\ufffb]/g, "");
  const plain = (s: string) => new Text(s.split("\n").map((l) => theme.fg("toolOutput", l)).join("\n"), 0, 0);
  const bodyAt = text.indexOf("\n\n") + 2;
  if (expanded && !renderContext.isError && bodyAt > 1 && !/^Type: .*\| Status: (?:running|error)\b/m.test(text.slice(0, bodyAt))) {
    const convAt = text.indexOf("\n\n--- Agent Conversation ---\n", bodyAt);
    const box = new Container();
    box.addChild(plain(text.slice(0, bodyAt - 1)));
    box.addChild(new Markdown(text.slice(bodyAt, convAt < 0 ? undefined : convAt), 0, 0, getMarkdownTheme(), { color: (t: string) => theme.fg("toolOutput", t) }));
    if (convAt >= 0) box.addChild(plain(text.slice(convAt + 1)));
    return box;
  }
  const lines = text.split("\n");
  const more = expanded ? 0 : Math.max(0, lines.length - 10);
  const hint = more ? `${theme.fg("muted", `\n... (${more} more lines,`)} ${keyHint("app.tools.expand", "to expand")}${theme.fg("muted", ")")}` : "";
  return new Text(lines.slice(0, lines.length - more).map((l) => theme.fg("toolOutput", l)).join("\n") + hint, 0, 0);
},
